#include "player.h"
#include "Engine/portal.h"
#include "Engine/render.h"
#include "Engine/state.h"
#include <stdlib.h>
static vec3s world_normal(const level_quad_t*q){f32 ry[16],rx[16],rz[16],m[16],t[16];mat4_rotate_y(ry,-DEG2RAD(q->rot.y));mat4_rotate_x(rx,-DEG2RAD(q->rot.x));mat4_rotate_z(rz,-DEG2RAD(q->rot.z));mat4_multiply(t,rx,ry);mat4_multiply(m,rz,t);return vec3_normalize((vec3s){m[8],m[9],m[10]});}
static bool seen(const level_quad_t*const*used,i32 n,const level_quad_t*q){for(i32 i=0;i<n;++i)if(used[i]==q)return true;return false;}
void game_player_shoot(level_data_t*l){if(!l||!l->sectors||state.id!=STATE_PLAYING||!state.cam)return;vec3s origin=state.cam->pos,direction=state.cam->front;const level_quad_t*used[MAX_PORTAL_DEPTH+1]={0};i32 used_count=0;vec3s path[MAX_DEBUG_TRACE_POINTS];i32 path_count=0;vec3s normal={0,1,0};bool wall=false;for(i32 depth=0;depth<=MAX_PORTAL_DEPTH&&path_count+2<=MAX_DEBUG_TRACE_POINTS;++depth){f32 nearest_t=1e30f;vec3s nearest_hit={0};const level_quad_t*nearest=NULL;for(i32 s=0;s<l->sector_count;++s){const level_sector_data_t*sec=&l->sectors[s];for(i32 q=0;q<sec->quad_count;++q){const level_quad_t*quad=&sec->quads[q];if(quad->is_invisible||seen(used,used_count,quad))continue;f32 t=0;vec3s hit;if(level_ray_intersects_quad(origin,direction,quad,&t,&hit,NULL)&&t>.001f&&t<nearest_t){nearest_t=t;nearest_hit=hit;nearest=quad;}}}if(!nearest)break;path[path_count++]=origin;path[path_count++]=nearest_hit;if(nearest->portal_id<=0){normal=world_normal(nearest);wall=true;break;}portal_link_t link;if(!portal_find_link(l,nearest,&link))break;if(used_count<(i32)(sizeof(used)/sizeof(used[0])))used[used_count++]=nearest;camera_t in={.pos=origin,.front=direction,.up={0,1,0}},out;if(!portal_build_camera(link.src,link.dst,&in,&out))break;origin=out.pos;direction=out.front;}if(wall&&path_count>=2){const vec3s color={(f32)(rand()%256)/255,(f32)(rand()%256)/255,(f32)(rand()%256)/255};render_debug_trace_add(path,path_count,normal,color);}}
